.badge {
  font-size: var(--bs-badge-font-size);
  padding: var(--bs-badge-padding-y) var(--bs-badge-padding-x);
}

@mixin button-variant($background, $border, $color: color-contrast($background)) {
  --bs-btn-color: #{$color};
  --bs-btn-bg: #{$background};
  --bs-btn-border-color: #{$border};
}

.btn-purple {
  --bs-btn-color: #fff;
  --bs-btn-bg: #6f42c1;
  --bs-btn-border-color: #6f42c1;
  --bs-btn-hover-bg: #59359a;
  --bs-btn-hover-border-color: #533190;
}

.translate-middle {
  transform: translate(-50%, -50%) !important;
}

.stretched-link::after {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 1;
  content: "";
}

const myAlert = document.getElementById('myAlert');
myAlert.addEventListener('close.bs.alert', (e) => {
  if (!confirm('Dismiss this alert?')) {
    e.preventDefault();
  }
});

.list-group-item.active {
  z-index: 2;
  color: var(--bs-list-group-active-color);
  background-color: var(--bs-list-group-active-bg);
  border-color: var(--bs-list-group-active-border-color);
}

@keyframes spinner-border {
  to { transform: rotate(360deg); }
}

@keyframes progress-bar-stripes {
  0% { background-position-x: 1rem; }
}

.progress-bar {
  transition: var(--bs-progress-bar-transition);
}

.btn-group > .btn:hover {
  z-index: 2;
}

.card-header, .card-footer {
  padding: var(--bs-card-cap-padding-y) var(--bs-card-cap-padding-x);
}

.alert .alert-link {
  color: var(--bs-alert-link-color);
}

.spinner-border {
  border: var(--bs-spinner-border-width) solid currentcolor;
  border-right-color: transparent;
}

.btn {
  line-height: var(--bs-btn-line-height);
}

.spinner-grow {
  animation: var(--bs-spinner-animation-speed, 0.75s) linear infinite spinner-grow;
}

tabEl.addEventListener('show.bs.tab', (event) => {
  console.log(event.target);
});

.card-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: auto 1fr auto;
}
.card {
  display: grid;
  grid-template-rows: subgrid;
  grid-row: span 3;
}

